// src/services/api.js
const BASE_URL = '';

/**
 * Core helper for all HTTP requests.
 * - Uses fetch() under the hood
 * - Includes credentials (cookies) if any
 * - Parses JSON automatically
 * - Wraps plain-text responses into { message: ... } objects
 * - Throws on non-OK status with an Error(message)
 */
async function request(path, options = {}) {
  const response = await fetch(`${BASE_URL}${path}`, {
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', ...options.headers },
    ...options,
  });

  // Handle HTTP errors
  if (!response.ok) {
    let errMsg = `Request failed: ${response.status}`;
    try {
      // Try to parse a JSON error body { message: "..." }
      const errJson = await response.json();
      errMsg = errJson.message || errMsg;
    } catch {
      // ignore JSON parse errors
    }
    throw new Error(errMsg);
  }

  //parser
  const contentType = response.headers.get('content-type') || '';
  if (contentType.includes('application/json')) {
    return response.json();
  } else {
    // plain text → wrap in JSON object
    const text = await response.text();
    return { message: text };
  }
}

// Authentication
export function login(credentials) {
  return request('/users/login', {
    method: 'POST',
    body: JSON.stringify(credentials),
  });
}

export function register(data) {
  return request('/users/register', {
    method: 'POST',
    body: JSON.stringify(data),
  });
}

// Questions
export function getQuestions() {
  return request('/questions');
}

export function getQuestionById(id) {
  return request(`/questions/${id}`);
}

export function postQuestion(question) {
  return request('/questions', {
    method: 'POST',
    body: JSON.stringify(question),
  });
}

// Answers
export function getAnswersByQuestionId(questionId) {
  return request(`/answers/question/${questionId}`);
}

export function postAnswer(answer) {
  // answer{ text, question: { id }, user: { id } }
  return request('/answers', {
    method: 'POST',
    body: JSON.stringify(answer),
  });
}
